18	
19	import java.util.Optional;
20	
21	/**
22	 * Normalization and comparison of owner telephone numbers. Kept separate from the owner controller
23	 * and the {@code Owner} model so the rules for shaping and comparing a telephone live in one place,
24	 * as pure functions with no web or persistence dependencies.
25	 *
26	 * <p>A submitted telephone is reduced to its canonical <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
27	 * form, which is the value stored and returned. Spaces, dashes and brackets are stripped; a leading
28	 * {@code '+'} and its country code are kept when present, otherwise the country code {@code '+61'} is
29	 * assumed and a single leading {@code '0'} is dropped from the national digits. The result is accepted
30	 * only when 8 to 15 digits follow the {@code '+'}. Two telephones denote the same number when their
31	 * {@linkplain #toComparisonKey(String) comparison keys} — their E.164 forms — are equal.
32	 */
33	public abstract class TelephoneNormalizer {
34	
35	    /** Characters stripped from a submitted telephone: spaces, dashes and brackets. */
36	    private static final String SEPARATORS = "[\\s()\\[\\]-]";
37	
38	    private static final int MIN_E164_DIGITS = 8;
39	
40	    private static final int MAX_E164_DIGITS = 15;
41	
42	    /**
43	     * Reduce a submitted telephone to its canonical E.164 form, which is the value to be stored and
44	     * returned. Spaces, dashes and brackets are removed; when the number carries a leading {@code '+'}
45	     * its country code is kept, otherwise country code {@code 61} is assumed and a single leading
46	     * {@code '0'} is dropped from the national digits. The result is accepted only when 8 to 15 digits
47	     * follow the {@code '+'}.
48	     *
49	     * @param rawTelephone the submitted telephone (non-null)
50	     * @return the canonical E.164 telephone (e.g. {@code +61412345678}), or {@link Optional#empty()}
51	     *         if {@code rawTelephone} cannot form a valid E.164 number
52	     */
53	    public static Optional<String> normalize(String rawTelephone) {
54	        String cleaned = rawTelephone.replaceAll(SEPARATORS, "");
55	        String digits;
56	        if (cleaned.startsWith("+")) {
57	            digits = cleaned.substring(1);
58	        }
59	        else {
60	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
61	            digits = "61" + national;
62	        }
63	        if (!digits.matches("\\d+") || digits.length() < MIN_E164_DIGITS || digits.length() > MAX_E164_DIGITS) {
64	            return Optional.empty();
65	        }
66	        return Optional.of("+" + digits);
67	    }
68	
69	    /**
70	     * The key used to decide whether two telephones denote the same number: the telephone's canonical
71	     * E.164 form, so telephones stored in different textual shapes still compare equal. A value that
72	     * does not form a valid E.164 number (e.g. legacy data) falls back to its separator-stripped form.
73	     *
74	     * @param telephone a stored or already-normalized telephone (non-null)
75	     * @return the comparison key
76	     */
77	    public static String toComparisonKey(String telephone) {
78	        return normalize(telephone).orElseGet(() -> telephone.replaceAll(SEPARATORS, ""));
79	    }
80	
81	}
