235	    /**
236	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
237	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
238	     * the request body already rejects null and empty values, but permits whitespace-only strings
239	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
240	     * that gap so every required field must carry a non-blank value.
241	     *
242	     * @param ownerFieldsDto the submitted owner fields
243	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
244	     */
245	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
246	        List<String> missing = new ArrayList<>();
247	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
248	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
249	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
250	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
251	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
252	        if (!missing.isEmpty()) {
253	            throw new InvalidOwnerFieldsException(missing);
254	        }
255	    }
256	
257	    private void addIfBlank(List<String> missing, String fieldName, String value) {
258	        if (value == null || value.isBlank()) {
259	            missing.add(fieldName);
260	        }
261	    }
262	
263	    /**
264	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
265	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
266	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
267	     * {@code 400 Bad Request}.
268	     *
269	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
270	     *                       {@link #rejectBlankOwnerFields} having already run)
271	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
272	     */
273	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
274	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
275	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
276	        ownerFieldsDto.setTelephone(normalized);
277	    }
278	
279	    /**
280	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
281	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
282	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
283	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
284	     *
285	     * @param ownerFieldsDto the submitted owner fields
286	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
287	     */
288	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
289	        String email = ownerFieldsDto.getEmail();
290	        if (email == null || email.isBlank()) {
291	            return;
292	        }
293	        email = email.trim();
294	        if (!EMAIL_PATTERN.matcher(email).matches()) {
295	            throw new InvalidOwnerFieldsException(List.of("email"));
296	        }
297	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
298	    }
299	
300	    /**
301	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
302	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
303	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
304	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
305	     *
306	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
307	     *                            {@link #normalizeTelephone}
308	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
309	     */
310	    private void rejectDuplicateTelephone(String normalizedTelephone) {
311	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
312	        boolean inUse = this.clinicService.findAllOwners().stream()
313	            .map(Owner::getTelephone)
314	            .filter(Objects::nonNull)
315	            .map(TelephoneNormalizer::toComparisonKey)
316	            .anyMatch(comparisonKey::equals);
317	        if (inUse) {
318	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
319	        }
320	    }
321	
322	    /**
323	     * Rejects creating an owner who shares a household with any existing owner, unless the request
324	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
325	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
326	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
327	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
328	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
329	     *
330	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
331	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
332	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
333	     *                                          request did not opt in with {@code sharesHousehold}
334	     */
335	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
336	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
337	            return;
338	        }
339	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
340	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
341	        boolean inUse = this.clinicService.findAllOwners().stream()
342	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
343	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
344	            .anyMatch(comparisonKey::equals);
345	        if (inUse) {
346	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
347	        }
348	    }
349	}
